struct BakedPose { r0: vec4<f32>, r1: vec4<f32>, r2: vec4<f32> };
fn bakedMix(a: BakedPose, b: BakedPose, weight: f32) -> BakedPose {
    return BakedPose(mix(a.r0, b.r0, weight), mix(a.r1, b.r1, weight), mix(a.r2, b.r2, weight));
