/** `navigator.storage.estimate()`'s answer, or a test's. */
export interface StorageEstimateLike {
    readonly quota?: number;
    readonly usage?: number;
}

/** A film in OPFS, as listFilms finds it. */
export interface StoredFilm {
    readonly exportId: string;
    /** `unknown` when its manifest is missing or unreadable (it was cut off before writing one). */
    readonly status: FilmManifest['status'] | 'unknown';
    readonly name: string | null;
    readonly container: string | null;
    readonly mimeType: string | null;
    readonly created: string | null;
    readonly updated: string | null;
    readonly frames: number | null;
    readonly bytes: number | null;
    /** A writer holds the film's lock, so it is being written now; null where Web Locks are missing. */
    readonly live: boolean | null;
    readonly report: unknown;
    /** The payload, for a video; null for a PNG sequence, or when there is none. */
    getFile(): Promise<File | null>;
    /** A PNG sequence's frames folder, or null. */
    getFrames(): Promise<FileSystemDirectoryHandle | null>;
}

/** A film's frames in, its file out: the video sink, or the PNG sink. */
export interface VideoSink {
    readonly codec: FilmCodec;
    readonly mimeType: string;
    /** The encoder config mediabunny settled on; null until the first frame configures the encoder (and for PNG). */
    readonly encoderConfig: VideoEncoderConfig | null;
    /** Frames encoded (a video's packets, a sequence's files). */
    readonly packets: number;
    readonly keyPackets: number;
    /** Encoded payload so far, in bytes: what the memory budget limits. */
    readonly bytes: number;
    /**
     * Takes ownership of `frame` (§4.6): it is closed whether the add succeeds or fails, and closed by the
     * sink even when wrapping it fails. Resolves when the encoder and the writer can take more.
     */
    add(frame: VideoFrame): Promise<void>;
    /** Flush the encoder and finalize the file: the film in memory as a Blob, or null once its file is committed. */
    finish(): Promise<Blob | null>;
    /** Stop and discard: nothing it wrote is kept (a file's writable is aborted). Idempotent. */
    cancel(): Promise<void>;
}

export interface VideoSinkOptions {
    readonly mediabunny: MediabunnyLike;
    readonly width: number;
    readonly height: number;
    readonly fps: number;
    /** J: the track declares it, and no more are taken. */
    readonly frames: number;
    readonly output: FilmOutput;
    /** Bits a second, resolved (`output.bitrate ?? bitrateFor(…)`). */
    readonly bitrate: number;
    /** The file the muxer writes through (OPFS, or a picked file); absent, the film stays in memory. */
    readonly gate?: FileStreamGate | null;
}

/**
 * The default bitrate, bits a second: MetaForge's measured rule, w × h × fps × 0.16 (about 20 Mbit/s
 * at 1080p60 and 80 at 4K60). Spike S1 found a hardware encoder that delivers far less at 4K; rate
 * control is the user's parked Q9.
 */
export declare function bitrateFor(width: number, height: number, fps: number): number;

/**
 * `(t) => view` through the keyframes (checked by readCamera), or null when there are none: the scene's
 * own view then holds. Each call returns a new object.
 */
export declare function cameraPath(keyframes: readonly CameraKeyframe[]): ((t: number) => CameraView) | null;

/**
 * The runtime stop (§8, Q10): throws when a measured operation exceeds `stopMs` and is not excused as a single
 * outlier after a fast calibration (`< stopMs / 4`). `at` is the frame being made, or `'warm-up'` before frame 0.
 */
export declare function checkOperation(ms: number, at: number | 'warm-up', stopMs: number): void;

/**
 * Compare the film's predicted size (predictBytes) with what OPFS reports free, as the Node tool checks
 * free disk. An estimate, not a reservation: quota, eviction and the encoder's real output can still
 * change the outcome, so a write can fail later anyway. Without quota figures nothing is refused.
 */
export declare function checkStorage(neededBytes: number, estimate: StorageEstimateLike): {
    readonly needed: number;
    readonly available: number | null;
};

/**
 * Of the app's codecs, those the container holds and WebCodecs can encode at this size, rate and bitrate,
 * in the app's order. The probe and the video sink choose the same way. When none is left, `reasons` gets a
 * refusal naming the smaller sizes, from a fixed ladder, that were probed and do have an encoder (§8).
 */
export declare function chooseCodecs(mb: MediabunnyLike, width: number, height: number, fps: number, container: FilmContainer, requested: readonly FilmCodec[], bitrate: number | undefined, reasons: string[]): Promise<FilmCodec[]>;

/**
 * A frame of `frameAspect`, shown whole on a canvas of `canvasAspect` (MetaForge's `containView`). On a
 * narrower canvas the vertical field of view widens until the frame's full width fits, so a guide drawn
 * min(width, height × frameAspect) wide marks exactly what the film will contain.
 */
export declare function containAspect(view: CameraView, frameAspect: number, canvasAspect: number, options?: FitAspectOptions): CameraView;

/**
 * CRC-32, the polynomial of PNG and zlib, of `bytes`. Pass a previous result as `crc` to continue over
 * more bytes, as Node's `zlib.crc32(data, value)` does.
 */
export declare function crc32(bytes: Uint8Array, crc?: number): number;

/**
 * Encode `rgba` (width × height × 4 bytes, row-major, top row first) as an 8-bit RGBA PNG: one IDAT of
 * unfiltered scanlines. The bytes come back exactly, alpha included.
 */
export declare function encodePNG(rgba: Uint8Array, width: number, height: number): Promise<Uint8Array>;

/**
 * Frame j's timestamp and duration (§4.3): quantized once, the same for canvas and readback frames. A
 * `VideoFrame` takes microseconds; mediabunny's `VideoSample` reads seconds back from it.
 */
export declare function frameStamp(index: number, fps: number): FrameStamp;

/**
 * Every film in OPFS, oldest first: completed and partial ones (kept until the app removes them), and
 * incomplete ones, `live` when a writer, in this tab or another, holds its lock (§4.5). Lists; changes nothing.
 */
export declare function listFilms(): Promise<StoredFilm[]>;

/**
 * Open a film's export in OPFS: take its lock, make null-graph-films/<exportId>/, write its manifest
 * (`writing`), and open the payload's writable (a video) or the frames' folder (a PNG sequence). What
 * fails part-way is undone before the error leaves.
 */
export declare function openOpfsExport(o: OpenStorageOptions): Promise<FilmStorage>;

/**
 * Open a file the user picked (§4.5): the app obtained `handle` in a user gesture; the library never opens a
 * picker, asks for permission, or deletes the file. A writable the browser refuses is refused in plain words.
 */
export declare function openPickedFile(handle: FileSystemFileHandle, exportId: string): Promise<FilmStorage>;

/** The plan for a film whose workload steps `dt` seconds at a time. Refuses, by name, what it cannot film. */
export declare function planFilm(film: FilmTiming, { dt }: {
    readonly dt: number;
}): FilmPlan;

/**
 * The keyframes, checked and copied: `t` from 0 and rising; a target of three numbers; a distance above
 * zero; angles that are numbers. `fov`, when any keyframe gives one, must be on every keyframe, above 0
 * and below 180 degrees. The Node tool's films give none; MetaForge's give it on every key.
 */
export declare function readCamera(keyframes: unknown): CameraKeyframe[];

/**
 * The app's `film` option, checked and completed. Its width and height must be even: H.264 and VP9 encode
 * 4:2:0, one chroma sample per 2 × 2 pixels.
 */
export declare function readFilm(film: unknown): FilmSettings;

/** The limits, checked: positive, and never above the defaults. */
export declare function readGuardLimits(limits?: FilmGuardLimits): {
    readonly limitMs: number;
    readonly stopMs: number;
};

/**
 * Remove one film from OPFS, completed or not, once no writer holds its lock: the app's explicit deletion
 * (§4.5). Refuses, by name, a film being written now. Without Web Locks, a film whose writable is still open
 * in another tab cannot be removed either: the browser refuses that removal itself.
 */
export declare function removeFilm(exportId: string): Promise<void>;

/**
 * One frame, drawn on an engine of its own (never the app's canvas, never resized) and read back exactly
 * (§6). The workload is built, drawn once at `seconds` with `view`, and disposed: nothing is stepped, so a
 * simulation shows its initial state unless `createWorkload` builds a later one.
 */
export declare function snapshot(o: SnapshotOptions): Promise<FilmSnapshot>;
